new:
CompletionStatus::Pending | CompletionStatus::NotApplicable => {
    let message = format!(
        "Runtime evaluator exited with {exit_code:?} without resolving the required visual_evaluation gate; runtime repair is required."
    );
    let _ = self.host.record_event(
        run_id,
        AgentEventKind::Failure,
        message.clone(),
    );
    if self
        .host
        .run(run_id)
        .is_ok_and(|run| run.state == AgentRunState::Evaluating)
    {
        let _ = self.host.transition_run(
            run_id,
            AgentRunState::Repairing,
            "Runtime evaluator did not resolve visual evidence; repair is required.",
        );
    }
    self.status = Some(message);
}
